// ── Pipeline 1: Router ──────────────────────────────────────
const item = $input.first();
const body = item.json.body ?? item.json;

let updateType = 'unknown';
let chatId     = null;
let userId     = null;
let text       = null;
let fileId     = null;
let mediaGroupId = null;
let messageId    = null;
let callbackQueryId = null;
let callbackData    = null;

if (body.message) {
  const msg = body.message;
  chatId       = msg.chat.id;
  userId       = String(msg.from.id);
  messageId    = msg.message_id;
  mediaGroupId = msg.media_group_id ?? null;

  if (msg.text) {
    updateType = 'text';
    text       = msg.text;
  } else if (msg.photo && msg.photo.length > 0) {
    updateType = 'photo';
    fileId     = msg.photo[msg.photo.length - 1].file_id;
  } else if (msg.document) {
    updateType = 'document';
    fileId     = msg.document.file_id;
  }
} else if (body.callback_query) {
  const cb = body.callback_query;
  chatId          = cb.message.chat.id;
  userId          = String(cb.from.id);
  messageId       = cb.message.message_id;
  callbackQueryId = cb.id;
  callbackData    = cb.data;
  updateType      = 'callback_query';
}

if (!userId) {
  return [{ json: { skip: true, reason: 'no_user_id' } }];
}

return [{
  json: {
    updateType, chatId, userId, text, fileId,
    mediaGroupId, messageId, callbackQueryId, callbackData,
  },
}];

// ── Pipeline 1: State Merge ──────────────────────────────────
const routerData = $('Pipeline 1: Router').first().json;

let dbUser = {};
try {
  const nocoResp = $('NocoDB Find User').first().json;
  if (nocoResp.list && nocoResp.list.length > 0) {
    dbUser = nocoResp.list[0];
  } else {
    dbUser = $('NocoDB Create User').first().json;
  }
} catch (_) {}

const userState    = dbUser.state         ?? 'empty';
const currentIndex = dbUser.current_index ?? 0;
const rowId        = dbUser.Id            ?? null;
const images = (() => {
  const raw = dbUser.images;
  if (!raw) return [];
  if (typeof raw === 'string') { try { return JSON.parse(raw); } catch (_) { return []; } }
  return Array.isArray(raw) ? raw : [];
})();

const { updateType } = routerData;
let routeKey;
if (updateType === 'callback_query') {
  routeKey = 'pipeline4';
} else if (updateType === 'photo' && (userState === 'empty' || userState === 'collecting')) {
  routeKey = 'pipeline2';
} else if (updateType === 'text' && (userState === 'tagging' || userState.startsWith('editing_'))) {
  routeKey = 'pipeline3';
} else {
  routeKey = 'unknown';
}

return [{ json: { ...routerData, userState, currentIndex, images, rowId, routeKey } }];

// ── Pipeline 2: Aggregate photos ────────────────────────────
const items = $input.all();
const seenIds  = new Set();
const newPhotos = [];
for (const it of items) {
  const fid = it.json.fileId;
  if (fid && !seenIds.has(fid)) { seenIds.add(fid); newPhotos.push({ file_id: fid, tag: null }); }
}
const base     = items[0].json;
const existing = Array.isArray(base.images) ? base.images : [];
const existingIds  = new Set(existing.map(p => p.file_id));
const toAdd        = newPhotos.filter(p => !existingIds.has(p.file_id));
const mergedImages = [...existing, ...toAdd].slice(0, 8);
return [{ json: { ...base, mergedImages, totalPhotos: mergedImages.length } }];

// ── Pipeline 3: Tagging Engine ───────────────────────────────
const item = $input.first();
const { text, images, currentIndex, userState, rowId, chatId, messageId } = item.json;

let targetIndex = currentIndex;
if (userState && userState.startsWith('editing_')) {
  const x = parseInt(userState.split('_')[1], 10);
  if (!Number.isNaN(x) && x >= 0 && x < images.length) targetIndex = x;
}

const updatedImages = images.map((img, idx) =>
  idx === targetIndex ? { ...img, tag: text } : img
);

let newIndex = currentIndex;
let newState, nextFileId = null, nextPhotoNumber = null;

if (userState && userState.startsWith('editing_')) {
  newState = 'review';
} else {
  newIndex = currentIndex + 1;
  if (newIndex < updatedImages.length) {
    newState         = 'tagging';
    nextFileId       = updatedImages[newIndex].file_id;
    nextPhotoNumber  = newIndex + 1;
  } else {
    newState = 'review';
  }
}

const nocoBody = { state: newState, images: JSON.stringify(updatedImages), current_index: newIndex };
return [{ json: { ...item.json, updatedImages, newIndex, newState, nextFileId, nextPhotoNumber, nocoBody, rowId } }];

// ── Pipeline 3 / 4: Build Review Report ─────────────────────
const item = $input.first();
const images = Array.isArray(item.json.updatedImages) ? item.json.updatedImages : (Array.isArray(item.json.images) ? item.json.images : []);
const lines = images.map((img, i) => `Изображение ${i + 1} — ${img.tag ?? '(без тега)'}`);
const reviewText = lines.join('\n');
const editButtons = images.map((img, i) => [{ text: `✏️ Изменить фото ${i + 1}`, callback_data: `edit_${i}` }]);
editButtons.push([{ text: '✅ Готово', callback_data: 'done' }]);
const reviewKeyboard = { inline_keyboard: editButtons };
return [{ json: { ...item.json, reviewText, reviewKeyboard } }];

// ── Pipeline 4: Callback Handler ────────────────────────────
const item = $input.first();
const { callbackData, callbackQueryId, chatId, messageId, images, currentIndex, rowId } = item.json;

let nocoBody = null, tgAction = null, tgBody = null, routeKey = 'noop', newIndex = currentIndex;

function tagKeyboard(idx) {
  const btns = [];
  if (idx > 0) btns.push({ text: '◀ Назад', callback_data: 'back' });
  btns.push({ text: '✖ Отмена', callback_data: 'cancel' });
  return { inline_keyboard: [btns] };
}

if (callbackData === 'cancel') {
  nocoBody = { state: 'empty', images: JSON.stringify([]), current_index: 0 };
  tgAction = 'deleteMessage';
  tgBody   = { chat_id: chatId, message_id: messageId };
  routeKey = 'cancel';
} else if (callbackData === 'back') {
  newIndex = Math.max(0, currentIndex - 1);
  nocoBody = { state: 'tagging', current_index: newIndex };
  tgAction = 'editMessageMedia';
  tgBody   = { chat_id: chatId, message_id: messageId, media: { type: 'photo', media: images[newIndex]?.file_id ?? '', caption: `Назначьте тег для фото №${newIndex + 1}` }, reply_markup: tagKeyboard(newIndex) };
  routeKey = 'back';
} else if (callbackData === 'start_tagging') {
  newIndex = 0;
  nocoBody = { state: 'tagging', current_index: 0 };
  tgAction = 'sendPhoto';
  tgBody   = { chat_id: chatId, photo: images[0]?.file_id ?? '', caption: 'Назначьте тег для фото №1', reply_markup: tagKeyboard(0) };
  routeKey = 'start_tagging';
} else if (callbackData === 'done') {
  nocoBody = { state: 'empty', images: JSON.stringify([]), current_index: 0 };
  tgAction = 'answerCallbackQuery';
  tgBody   = { callback_query_id: callbackQueryId, text: '✅ Теги сохранены!' };
  routeKey = 'done';
} else if (callbackData && callbackData.startsWith('edit_')) {
  const x = parseInt(callbackData.split('_')[1], 10);
  if (!Number.isNaN(x) && x >= 0 && x < images.length) {
    nocoBody = { state: `editing_${x}`, current_index: x };
    tgAction = 'editMessageMedia';
    tgBody   = { chat_id: chatId, message_id: messageId, media: { type: 'photo', media: images[x].file_id, caption: `Введите новый тег для фото №${x + 1}` }, reply_markup: tagKeyboard(x) };
    routeKey = 'edit';
  }
} else if (callbackData === 'show_review') {
  routeKey = 'show_review';
}

const answerCbBody = { callback_query_id: callbackQueryId };
return [{ json: { ...item.json, nocoBody, tgAction, tgBody, answerCbBody, routeKey, newIndex } }];
